const defaults = Object.freeze({ abortEarly: false, allowUnknown: false });

export function normalizeConfig(options = {}) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError('Configuration must be an object');
  }
  for (const key of Object.keys(options)) {
    if (!Object.hasOwn(defaults, key)) throw new TypeError(`Unknown option: ${key}`);
    if (typeof options[key] !== 'boolean') throw new TypeError(`${key} must be boolean`);
  }
  return Object.freeze({ ...defaults, ...options });
}
